def need(value, message):
    if not value: raise ValueError(message)

def restore(name, source):
    expected, rows = SPEC[name]
    for old, new in reversed(rows):
        need(source.count(new) == 1, 'Exact inverse fragment required')
        source = source.replace(new, old, 1)
    need(hashlib.sha256(source.encode('utf-8')).hexdigest() == expected, 'Exact predecessor inverse required')
    return source

def derive(name, source):
    expected, rows = SPEC[name]
    need(hashlib.sha256(source.encode('utf-8')).hexdigest() == expected, 'Exact predecessor source required')
    original = source
    for old, new in rows:
        need(source.count(old) == 1, 'Exact predecessor fragment required')
        source = source.replace(old, new, 1)
    need(restore(name, source) == original, 'Raw source inverse differs')
    return source
